)
INSERT INTO "BlogPost" ("id", "slug", "title", "excerpt", "contentHtml", "coverImage", "seoTitle", "seoDescription", "pillarPageId", "status", "publishedAt", "createdAt", "updatedAt")
SELECT c."id", c."slug", c."title", c."excerpt", c."contentHtml", c."coverImage", c."seoTitle", c."seoDescription", p."id", 'PUBLISHED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM content c JOIN eligible_pillars p ON p."slug" = c."pillarSlug"
WHERE (SELECT count(*) FROM eligible_pillars) = 3
  AND NOT EXISTS (SELECT 1 FROM "BlogPost" b JOIN content planned ON b."id" = planned."id" OR b."slug" = planned."slug");
